<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';const p=defineProps({host:Object});const form=useForm({name:p.host?.name||'',ip_address:p.host?.ip_address||'',description:p.host?.description||'',enabled:p.host?.enabled??true,interval_seconds:p.host?.interval_seconds||60,timeout_ms:p.host?.timeout_ms||2000,latency_threshold_ms:p.host?.latency_threshold_ms||200,retry_count:p.host?.retry_count||3});const submit=()=>p.host?form.put(route('hosts.update',p.host.id)):form.post(route('hosts.store'));</script>
<template><Head :title="host?'Edit branch':'Add branch'"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">{{host?'Edit branch':'Register branch IP'}}</h1><p class="text-xs text-slate-500">ICMP checks run server-side through queue workers</p></div></template><form @submit.prevent="submit" class="mx-auto max-w-3xl rounded-xl border border-slate-800 bg-slate-900 p-6"><div class="grid gap-5 sm:grid-cols-2"><label>Branch name<input v-model="form.name" required class="field"><small>{{form.errors.name}}</small></label><label>IP address<input v-model="form.ip_address" required placeholder="192.168.1.10 or 2001:db8::1" class="field font-mono"><small>{{form.errors.ip_address}}</small></label><label>Interval (seconds)<input v-model="form.interval_seconds" type="number" min="10" class="field"></label><label>Timeout (milliseconds)<input v-model="form.timeout_ms" type="number" min="100" class="field"></label><label>Latency threshold (ms)<input v-model="form.latency_threshold_ms" type="number" min="1" class="field"></label><label>Ping attempts<input v-model="form.retry_count" type="number" min="1" max="10" class="field"></label><label class="flex items-center gap-3 pt-7"><input v-model="form.enabled" type="checkbox" class="rounded border-slate-600 bg-slate-800 text-emerald-500"> Enable monitoring</label><label class="sm:col-span-2">Description<textarea v-model="form.description" rows="3" class="field"></textarea></label></div><div class="mt-6 flex justify-end gap-3"><Link :href="route('hosts.index')" class="rounded-lg border border-slate-700 px-4 py-2 text-sm">Cancel</Link><button :disabled="form.processing" class="rounded-lg bg-emerald-500 px-5 py-2 text-sm font-bold text-slate-950">{{host?'Save changes':'Add branch'}}</button></div></form></AuthenticatedLayout></template>
